fn named_query<D: Dom, const LO: u16, const HI: u16>(
    scope: &mut v8::PinScope,
    key: v8::Local<v8::Name>,
    args: v8::PropertyCallbackArguments,
    mut rv: v8::ReturnValue<v8::Integer>,
) -> v8::Intercepted {
    let Some(this) = rt::unwrap(&args.holder(), LO, HI) else {
        return v8::Intercepted::kNo;
    };
    let st = rt::state(scope);
    let dom = st.engine::<D>();
    let name = key.to_rust_string_lossy(scope);
    if <D as WindowImpl>::named_getter(dom, this, &name).is_none() {
        return v8::Intercepted::kNo;
    }
    rv.set_int32(2);
    v8::Intercepted::kYes
}

fn named_enumerate<D: Dom, const LO: u16, const HI: u16>(
    scope: &mut v8::PinScope,
    args: v8::PropertyCallbackArguments,
    mut rv: v8::ReturnValue<v8::Array>,
) {
    let Some(this) = rt::unwrap(&args.holder(), LO, HI) else {
        return;
    };
    let st = rt::state(scope);
    let dom = st.engine::<D>();
    let names = <D as WindowImpl>::supported_property_names(dom, this);
    let mut keys: Vec<v8::Local<v8::Value>> = Vec::with_capacity(names.len());
    for n in &names {
        let Some(k) = rt::str(scope, n) else { return };
        keys.push(k.into());
    }
    rv.set(v8::Array::new_with_elements(scope, &keys));
}

fn named_delete<D: Dom, const LO: u16, const HI: u16>(
    scope: &mut v8::PinScope,
    key: v8::Local<v8::Name>,
    args: v8::PropertyCallbackArguments,
    mut rv: v8::ReturnValue<v8::Boolean>,
) -> v8::Intercepted {
    let Some(this) = rt::unwrap(&args.holder(), LO, HI) else {
        return v8::Intercepted::kNo;
    };
    let st = rt::state(scope);
    let dom = st.engine::<D>();
    let name = key.to_rust_string_lossy(scope);
    if <D as WindowImpl>::named_getter(dom, this, &name).is_none() {
        return v8::Intercepted::kNo;
    }
    rv.set_bool(false);
    v8::Intercepted::kYes
}

